import java.io.*;

public class Main {
    static final byte[] BUF = new byte[1 << 16];
    static int len, ptr;

    static int read() throws IOException {
        if (ptr == len) {
            len = System.in.read(BUF, 0, BUF.length);
            ptr = 0;
            if (len <= 0) return -1;
        }
        return BUF[ptr++];
    }

    static long nextLong() throws IOException {
        int c = read();
        while (c != -1 && c <= ' ') c = read();
        boolean neg = c == '-';
        if (neg) c = read();
        long r = 0;
        while (c >= '0' && c <= '9') {
            r = r * 10 + (c - '0');
            c = read();
        }
        return neg ? -r : r;
    }

    public static void main(String[] args) throws IOException {
        int n = (int) nextLong();
        long[] a = new long[n], left = new long[n], right = new long[n];
        for (int i = 0; i < n; i++) a[i] = nextLong();
        // Best non-empty subarray sum inside every prefix and every suffix (Kadane both ways).
        long cur = a[0], best = a[0];
        left[0] = best;
        for (int i = 1; i < n; i++) {
            cur = Math.max(a[i], cur + a[i]);
            best = Math.max(best, cur);
            left[i] = best;
        }
        cur = best = a[n - 1];
        right[n - 1] = best;
        for (int i = n - 2; i >= 0; i--) {
            cur = Math.max(a[i], cur + a[i]);
            best = Math.max(best, cur);
            right[i] = best;
        }
        long answer = Long.MIN_VALUE;
        for (int i = 0; i + 1 < n; i++) answer = Math.max(answer, left[i] + right[i + 1]);
        System.out.println(answer);
    }
}

package main

import (
	"bufio"
	"fmt"
	"io"
	"math"
	"os"
)

var data []byte
var pos int

func nextInt() int64 {
	for pos < len(data) && data[pos] <= ' ' {
		pos++
	}
	neg := false
	if pos < len(data) && data[pos] == '-' {
		neg = true
		pos++
	}
	var r int64
	for pos < len(data) && data[pos] >= '0' && data[pos] <= '9' {
		r = r*10 + int64(data[pos]-'0')
		pos++
	}
	if neg {
		return -r
	}
	return r
}

func main() {
	data, _ = io.ReadAll(bufio.NewReader(os.Stdin))
	n := int(nextInt())
	a, left, right := make([]int64, n), make([]int64, n), make([]int64, n)
	for i := range a {
		a[i] = nextInt()
	}
	// Best non-empty subarray sum inside every prefix and every suffix (Kadane both ways).
	cur, best := a[0], a[0]
	left[0] = best
	for i := 1; i < n; i++ {
		cur = max(a[i], cur+a[i])
		best = max(best, cur)
		left[i] = best
	}
	cur, best = a[n-1], a[n-1]
	right[n-1] = best
	for i := n - 2; i >= 0; i-- {
		cur = max(a[i], cur+a[i])
		best = max(best, cur)
		right[i] = best
	}
	answer := int64(math.MinInt64)
	for i := 0; i+1 < n; i++ {
		answer = max(answer, left[i]+right[i+1])
	}
	fmt.Println(answer)
}
